ПАРЫ = [('    r\')[^\\n]*$\')\n\n\ndef _прибрать(текст: str) -> str:\n    """Дырки от удалённых строк убрать, но абзацный отступ перед подписью и\n    перед концовкой СОХРАНИТЬ.\n', '    r\')[^\\n]*$\')\n\n\n# ОДНА ФРАЗА ВМЕСТО ДВУХ У КЦ (владелец 14.10: «может объединим их, типо\n# прошу перенаправить ответственному, а если тема не актуальна кратко\n# ответить»). Просьба переслать и строка отказа шли двумя строками подряд и\n# читались хвостом из вежливостей. Склеиваем ТОЛЬКО если просьба в письме\n# уже есть: ЛПР по имени просьбу не получает (гейт), ему остаётся KONTSOVKA.\n# Хвост у всех вариантов одинаковый и совпадает с каноном: «буду признателен\n# за короткий ответ» ловят и _has_optout, и счётчик тавтологии.\nKONTSOVKA_KC_VARIANTY = (\n    \'Если вопрос не к вам, перешлите, пожалуйста, письмо ответственному \'\n    \'коллеге, а если тема сейчас неактуальна, буду признателен за короткий \'\n    \'ответ, чтобы в дальнейшем вас не отвлекать.\',\n    \'Если этим занимается другой специалист, перешлите, пожалуйста, письмо \'\n    \'ему, а если тема сейчас неактуальна, буду признателен за короткий ответ, \'\n    \'чтобы в дальнейшем вас не отвлекать.\',\n    \'Прошу перенаправить письмо ответственному за это направление, а если \'\n    \'тема сейчас неактуальна, буду признателен за короткий ответ, чтобы в \'\n    \'дальнейшем вас не отвлекать.\',\n)\n\n\ndef _прибрать(текст: str) -> str:\n    """Дырки от удалённых строк убрать, но абзацный отступ перед подписью и\n    перед концовкой СОХРАНИТЬ.\n'), ('    читают глазами, слипшийся хвост выглядит обрывком.\n    """\n    текст = re.sub(r\'[ \\t]*\\n[ \\t]*\\n[ \\t]*\\n+\', \'\\n\\n\', текст)\n    канон = re.escape(KONTSOVKA)\n    текст = re.sub(r\'\\n+(?=\' + канон + r\')\', \'\\n\\n\', текст)\n    текст = re.sub(канон + r\'\\n+(?=С уважением)\', KONTSOVKA + \'\\n\\n\', текст)\n    return текст.rstrip()\n\n\ndef _kontsovka_kc(текст: str) -> str:\n', '    читают глазами, слипшийся хвост выглядит обрывком.\n    """\n    текст = re.sub(r\'[ \\t]*\\n[ \\t]*\\n[ \\t]*\\n+\', \'\\n\\n\', текст)\n    for _к in (KONTSOVKA,) + KONTSOVKA_KC_VARIANTY:\n        канон = re.escape(_к)\n        текст = re.sub(r\'\\n+(?=\' + канон + r\')\', \'\\n\\n\', текст)\n        текст = re.sub(канон + r\'\\n+(?=С уважением)\', _к + \'\\n\\n\', текст)\n    return текст.rstrip()\n\n\ndef _vynut_prosbu(текст: str) -> tuple:\n    """Вынуть из письма отдельную фразу-просьбу переслать: (текст, была ли).\n\n    Только предложение БЕЗ «?»: модель бывает пишет просьбу вопросом и\n    слепляет её с единственным вопросом письма - его не трогаем. Подпись и\n    всё ниже «С уважением» не смотрим.\n    """\n    финал = re.search(r\'(?im)^\\s*с\\s+уважением\', текст)\n    тело, хвост = (текст[:финал.start()], текст[финал.start():]) if финал else (текст, \'\')\n    строки = тело.split(\'\\n\')\n    for н in range(len(строки) - 1, -1, -1):\n        фразы = re.split(r\'(?<=[.!?])\\s+\', строки[н])\n        for к in range(len(фразы) - 1, -1, -1):\n            ф = фразы[к]\n            if \'?\' in ф or not _prosba_perenapravit(ф):\n                continue\n            if re.search(r\'(?i)меня\\s+зовут\', ф):\n                continue\n            del фразы[к]\n            строки[н] = \' \'.join(фразы).strip()\n            return \'\\n\'.join(строки) + хвост, True\n    return текст, False\n\n\ndef _kontsovka_kc(текст: str) -> str:\n'), ('    единственным вопросом письма в одну фразу, и замена унесла бы вопрос.\n    Такое письмо пусть увидит гейт.\n    """\n    if KONTSOVKA in текст:\n        return _прибрать(текст)\n    if _СТАРЫЙ_ОТКАЗ_RE.search(текст):\n        def _заменить(m: \'re.Match\') -> str:\n            return m.group(0) if \'?\' in m.group(0) else KONTSOVKA\n        return _прибрать(_СТАРЫЙ_ОТКАЗ_RE.sub(_заменить, текст, count=1))\n    финал = re.search(r\'(?im)^\\s*с\\s+уважением\\s*,?\\s*$\', текст)\n    if финал:\n        return _прибрать(текст[:финал.start()].rstrip() + \'\\n\\n\'\n                         + KONTSOVKA + \'\\n\\n\' + текст[финал.start():].strip())\n    return _прибрать(текст + \'\\n\\n\' + KONTSOVKA)\n\n\ndef zashit_kontsovku(body: str, division: str = \'meyer\') -> str:\n', '    единственным вопросом письма в одну фразу, и замена унесла бы вопрос.\n    Такое письмо пусть увидит гейт.\n    """\n    # 14.10: просьба переслать и отказ - одной фразой (KONTSOVKA_KC_VARIANTY).\n    # Склейка уже стоит -> идемпотентно, только лишние отдельные строки прочь.\n    for _к in KONTSOVKA_KC_VARIANTY:\n        if _к in текст:\n            до, после = текст.split(_к, 1)\n            до = _СТАРЫЙ_ОТКАЗ_RE.sub(lambda m: m.group(0) if \'?\' in m.group(0) else \'\', до)\n            до, _ = _vynut_prosbu(до)\n            после = _СТАРЫЙ_ОТКАЗ_RE.sub(lambda m: m.group(0) if \'?\' in m.group(0) else \'\', после)\n            return _прибрать(до.rstrip() + \'\\n\\n\' + _к + после)\n    исходный = текст\n    без_просьбы, просьба = _vynut_prosbu(текст)\n    if просьба:\n        текст = без_просьбы\n    финал_фраза = (KONTSOVKA_KC_VARIANTY[sum(map(ord, текст[:400])) % len(KONTSOVKA_KC_VARIANTY)]\n                   if просьба else KONTSOVKA)\n    if KONTSOVKA in текст:\n        return _прибрать(текст.replace(KONTSOVKA, финал_фраза, 1))\n    if _СТАРЫЙ_ОТКАЗ_RE.search(текст):\n        замен = []\n\n        def _заменить(m: \'re.Match\') -> str:\n            if \'?\' in m.group(0):\n                return m.group(0)\n            замен.append(1)\n            return финал_фраза\n        новый = _СТАРЫЙ_ОТКАЗ_RE.sub(_заменить, текст, count=1)\n        # Отказ слеплен с вопросом - как и раньше, письмо не трогаем (и\n        # просьбу не теряем): его увидит гейт.\n        return _прибрать(новый if замен else исходный)\n    финал = re.search(r\'(?im)^\\s*с\\s+уважением\\s*,?\\s*$\', текст)\n    if финал:\n        return _прибрать(текст[:финал.start()].rstrip() + \'\\n\\n\'\n                         + финал_фраза + \'\\n\\n\' + текст[финал.start():].strip())\n    return _прибрать(текст + \'\\n\\n\' + финал_фраза)\n\n\ndef zashit_kontsovku(body: str, division: str = \'meyer\') -> str:\n')]
